cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');
const tables = db.prepare(\"SELECT name FROM sqlite_master WHERE type='table'\").all();
console.log('Tables:', tables.map(t => t.name));
for (const t of tables) {
  const cols = db.prepare('PRAGMA table_info(' + t.name + ')').all();
  console.log(t.name + ':', cols.map(c => c.name).join(', '));
  const count = db.prepare('SELECT COUNT(*) as c FROM ' + t.name).get();
  console.log('  rows:', count.c);
}
"

cd /workspace && node -e "
const Database = require('better-sqlite3');
const db = new Database('world.db');

// Look for reservation C4C633 in flight_bookings
const booking = db.prepare(\"SELECT * FROM flight_bookings WHERE booking_id = 'C4C633'\").get();
if (booking) {
  console.log(JSON.stringify(booking, null, 2));
} else {
  console.log('Not found in flight_bookings');
  // Search all bookings
  const all = db.prepare('SELECT booking_id FROM flight_bookings').all();
  console.log('All booking IDs:', all.map(b => b.booking_id));
}
"

